package io.appthreat.atom.slicing.callsites

import scala.util.Try

/** The constants Ruby's core and standard library define, from the committed list generated by
  * `gen-ruby-builtins.rb` (`ruby-builtins.txt`), never a hand-written one. A constant is a
  * dependency's use even though the project needs no gem for it (decision 0001, P3).
  */
private[callsites] object RubyBuiltins:

  /** `kind` is `c` (class), `m` (module) or `k` (any other constant); `plainNew` marks a class
    * whose `new` is the plain `Class#new`.
    */
  final case class Entry(kind: Char, plainNew: Boolean)

  val Resource = "/callsites/ruby-builtins.txt"

  /** The names run to four segments, as the list is generated. */
  val Depth = 4

  private lazy val entries: Map[String, Entry] = Try {
      val stream = getClass.getResourceAsStream(Resource)
      val text   = scala.io.Source.fromInputStream(stream, "UTF-8").mkString
      stream.close()
      text.linesIterator.filterNot(l => l.isEmpty || l.startsWith("#")).flatMap { line =>
          line.split(' ').toList match
            case kind :: name :: rest if kind.length == 1 =>
                Some(name -> Entry(kind.head, rest.contains("new")))
            case _ => None
      }.toMap
  }.getOrElse(Map.empty)

  /** The entry of exactly this constant path. */
  def exact(path: List[String]): Option[Entry] = entries.get(path.mkString("::"))

  /** Whether the path is a core or standard library constant: one the list names
    * (`JSON::ParserError`, `File::SEPARATOR`), or one under a class it names
    * (`Net::HTTP::Post::Deep`, past the list's depth). Under a module it does not name, the
    * constant is a gem's: gems add to the library's namespaces (`JSON::LD` is json-ld's,
    * `Net::LDAP` net-ldap's).
    */
  def contains(path: List[String]): Boolean =
      (math.min(path.size, Depth) to 1 by -1).iterator
          .flatMap(k => exact(path.take(k)).map(k -> _))
          .nextOption()
          .exists((k, entry) => k == path.size || entry.kind == 'c')
end RubyBuiltins
